void test_bind(const char *path)
{
	int sfd;
	struct sockaddr_un my_addr, peer_addr;

	sfd = socket(AF_UNIX, SOCK_STREAM, 0);

	if (sfd < 0) {
		fprintf(stderr, "Failed to open a socket for bind test\n");
		exit(1);
	}
	memset(&my_addr, 0, sizeof(struct sockaddr_un));
	my_addr.sun_family = AF_UNIX;
	strncpy(my_addr.sun_path, path,
			sizeof(my_addr.sun_path) - 1);
	if (bind(sfd, (struct sockaddr *) &my_addr,
				sizeof(struct sockaddr_un)) != -1) {
		fprintf(stderr, "leak at bind of %s\n", path);
		exit(1);
	}
	if (errno != ENOENT && errno != ENOSYS) {
		fprintf(stderr, "leak at bind of %s: errno was %s\n", path, strerror(errno));
		exit(1);
	}
	close(sfd);
}

static std::string BitsToFlags(uint32_t flags)
{
	std::string out;
	if (flags & SF_CTCP_USER)
		out.push_back('C');
	if (flags & SF_CTCP_CHANNEL)
		out.push_back('c');
	if (flags & SF_INVITE)
		out.push_back('i');
	if (flags & SF_NOTICE_USER)
		out.push_back('N');
	if (flags & SF_NOTICE_CHANNEL)
		out.push_back('n');
	if (flags & SF_PRIVMSG_USER)
		out.push_back('P');
	if (flags & SF_PRIVMSG_CHANNEL)
		out.push_back('p');
	if (flags & SF_TAGMSG_CHANNEL)
		out.push_back('T');
	if (flags & SF_TAGMSG_USER)
		out.push_back('t');
	if (flags & SF_EXEMPT)
		out.push_back('x');
	return out;
}

